const data = $('Convert String To JSON').first().json;

const basePath = 'C:\\Users\\Paradise Computers\\.n8n-files';

const paths = Object.keys(data).map(sceneName => {
  const safeSceneName = sceneName
    .replace(/[<>:"/\\|?*]/g, '_')
    .trim();

  return `${basePath}\\scenes\\scene_${safeSceneName}.mp4`;
});

const content = paths
  .map(path => `file '${path.replace(/\\/g, '/')}'`)
  .join('\n');

return [
  {
    json: {
      content
    }
  }
];
